import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Events Data Model
export interface UserActivityEvent {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number; // Will default nullable values to 0 during ingestion
}

// Configure the ingestion pipeline with table optimization for target query patterns:
// 1. Activity counts per user over a date range (user_id, event_ts)
// 2. Total duration per action type (action, event_ts for time-based aggregations)
export const UserActivityEventPipeline = new IngestPipeline<UserActivityEvent>("UserActivityEvent", {
  table: {
    orderByFields: ["userId", "eventTs", "action"] // Optimized for both query patterns
  },
  stream: true,
  ingestApi: true,
});

